Sql:
SELECT c.ClientID, c.LastName & ", " & c.FirstName AS ClientName, s.ServiceCode, s.ServiceName, p.ProviderName, csp.HoursPerWeek, csp.WeeklyCost, csp.AnnualEstCost, csp.Status, csp.FiscalYear
FROM tblServices AS s INNER JOIN (tblProviders AS p INNER JOIN ((tblClients AS c INNER JOIN tblClientServiceNeeds AS csn ON c.ClientID = csn.ClientID) INNER JOIN (tblProviderServiceCatalog AS psc INNER JOIN tblClientServicePlan AS csp ON psc.ProviderServiceCatalogID = csp.ProviderServiceCatalogID) ON csn.ClientServiceNeedID = csp.ClientServiceNeedID) ON p.ProviderID = psc.ProviderID) ON s.ServiceID = csn.ServiceID
ORDER BY c.LastName, c.FirstName, s.ServiceName;
